def make(i, row):
    tag, prompt, opts, answer, reason = row
    options = [{'id': chr(65+j), 'text': t} for j, t in enumerate(opts)]
    aid = next(o['id'] for o in options if o['text'] == answer)
    refs = [{'url': u, 'title': t + '；僅研究題型與能力方向，未複製原題。', 'year': '113-114', 'subject': 'social', 'locator': loc, 'observedPattern': '公開社會科產業調適資料題研究後原創改寫', 'reuseDecision': 'pattern-only', 'status': 'recorded', 'locatorLevel': 'paper'} for u, t, loc in SOURCES]
    steps = [f'讀題定位：圈出「{tag}」與題目給的挑戰、成本、風險、受益者或成效指標。', f'建立判準：{reason}', f'核對答案：選項 {aid}「{answer}」符合產業挑戰與調適的多因素判讀。', '排除誘答：檢查是否只看一個數字、單一事件、短期成果或忽略被轉移的成本。', '結論回查：確認基準線、期間、尺度與推論強度相配，並保留後續監測需求。']
    return {'id': f'question-social-content-geo-ae-iv-4-{i}', 'subject': 'social', 'type': 'single-choice', 'prompt': prompt, 'options': options, 'knowledgeIds': ['kg-social-content-geo-ae-iv-4'], 'difficulty': 'medium', 'answer': {'value': aid, 'explanation': reason}, 'provenance': {'origin': 'original', 'license': 'All rights reserved', 'sourceUrl': SOURCES[0][0], 'sourceLocator': '公立國中社會科公開試題；研究產業挑戰、調適策略、資料比較與政策成效的能力方向。', 'authoringNote': '依官方課綱 KG 與三個公立學校公開來源的題型／能力方向獨立改寫，未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。'}, 'reviewStatus': 'draft', 'updatedAt': '2026-09-09', 'lessonId': 'lesson-social-content-geo-ae-iv-4', 'examPatternRefs': refs, 'solutionStrategy': '先分辨產業挑戰與受影響對象，再用基準線、多指標與長期追蹤評估調適。', 'solutionSteps': steps}

for i, row in enumerate(DATA, 1):
    (OUT / f'question-social-content-geo-ae-iv-4-{i}.json').write_text(json.dumps(make(i, row), ensure_ascii=False, indent=2) + '\n')
